css:
:root { --primary: #10B981; --bg-gradient: #F3F4F6; --card-bg: #ffffff; --card-dark: #F9FAFB; --text-main: #1F2937; --text-muted: #6B7280; --border-color: #E5E7EB; --radius: 12px; --shadow-sm: 0 1px 2px 0 rgba(0,0,0,0.05); }
* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: "Segoe UI", Roboto, sans-serif; background: var(--bg-gradient); color: var(--text-main); line-height: 1.6; display: flex; flex-direction: column; min-height: 100vh; }
a { text-decoration: none; color: var(--primary); }
.site-header { background: #fff; border-bottom: 1px solid var(--border-color); box-shadow: var(--shadow-sm); position: sticky; top: 0; z-index: 1000; }
.header-container { max-width: 1200px; margin: 0 auto; padding: 12px 20px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 15px; }
.logo { font-size: 1.4rem; font-weight: 800; color: #111827; }
.search-input { padding: 10px 16px; border-radius: 8px; border: 1px solid var(--border-color); background: #F9FAFB; width: 300px;}
.header-nav { display: flex; gap: 15px; align-items: center; }
.btn-primary { background: var(--primary); color: #fff; padding: 8px 16px; border-radius: 8px; font-weight: 600; border: none; cursor: pointer; }
.layout-container { max-width: 1200px; margin: 30px auto; padding: 0 20px; display: flex; flex-direction: column; gap: 30px; flex-grow: 1; width: 100%; }
@media(min-width: 860px) { .layout-container { flex-direction: row; } }
.main-content { flex-grow: 1; width: 100%; }
@media(min-width: 860px) { .main-content { width: 72%; } }
.sidebar { width: 100%; display: flex; flex-direction: column; gap: 20px; }
@media(min-width: 860px) { .sidebar { width: 28%; } }
.card { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 24px; box-shadow: var(--shadow-sm); }
.widget-title { font-size: 1.1rem; border-bottom: 2px solid var(--primary); padding-bottom: 12px; margin-bottom: 16px; font-weight: 700; }
.stat-list li { display: flex; justify-content: space-between; padding: 8px 0; border-bottom: 1px solid var(--border-color); font-size: 0.95rem;}
.post-list { display: grid; gap: 16px; }
.post-item { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 20px; box-shadow: var(--shadow-sm); }
.post-title { font-size: 1.25rem; font-weight: 700; margin-bottom: 6px; }
.post-meta { display: flex; gap: 16px; font-size: 0.85rem; color: var(--text-muted); border-top: 1px solid var(--border-color); padding-top: 12px; margin-top: 10px;}
.message-block { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); margin-bottom: 16px; display: flex; flex-direction: column; box-shadow: var(--shadow-sm); }
@media(min-width: 640px) { .message-block { flex-direction: row; } }
.user-panel { background: #F9FAFB; padding: 20px; display: flex; align-items: center; border-bottom: 1px solid var(--border-color); }
@media(min-width: 640px) { .user-panel { width: 160px; border-bottom: none; border-right: 1px solid var(--border-color); flex-direction: column; text-align: center; flex-shrink: 0; } }
.user-panel img { width: 70px; height: 70px; border-radius: 50%; margin-bottom: 8px; }
.message-content { padding: 20px; flex-grow: 1; }
.message-header { display: flex; justify-content: space-between; border-bottom: 1px solid var(--border-color); padding-bottom: 10px; margin-bottom: 15px; font-size: 0.85rem; color: var(--text-muted); }
.badge { background: var(--primary); color: #fff; font-size: 0.7rem; padding: 3px 8px; border-radius: 6px; font-weight: 700; display: inline-block; }
.pagination { display: flex; justify-content: center; gap: 8px; margin-top: 40px; }
.page-link { padding: 8px 14px; border: 1px solid var(--border-color); border-radius: 8px; font-weight: 600; color: var(--text-main); }
.page-link.active { background: var(--primary); color: #fff; }
.site-footer { background: #fff; padding: 40px 20px; border-top: 1px solid var(--border-color); margin-top: auto; font-size: 0.9rem; }
.footer-container { max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 30px; }
